namespace platform {
struct Node {
    bool alive = true;
    uint32_t children = 0;
};
static int insertions = 0, invalid = 0;
static bool live(ArkUI_NodeHandle handle) {
    if (!handle || !reinterpret_cast<Node*>(handle)->alive) {
        ++invalid;
        return false;
    }
    return true;
}
static int32_t insert(ArkUI_NodeHandle handle) {
    ++insertions;
    return live(handle) ? ARKUI_ERROR_CODE_NO_ERROR : ARKUI_ERROR_CODE_PARAM_INVALID;
}
}

extern "C" int32_t OH_ArkUI_NodeContent_AddNode(ArkUI_NodeContentHandle, ArkUI_NodeHandle node) {
    return platform::insert(node);
}
extern "C" int32_t OH_ArkUI_NodeContent_InsertNode(ArkUI_NodeContentHandle, ArkUI_NodeHandle node, int32_t) {
    return platform::insert(node);
}
extern "C" int32_t OH_ArkUI_NodeContent_RemoveNode(ArkUI_NodeContentHandle, ArkUI_NodeHandle node) {
    assert(platform::live(node));
    return ARKUI_ERROR_CODE_NO_ERROR;
}
extern "C" int32_t OH_ArkUI_UnregisterDrawCallbackOnNodeHandle(ArkUI_NodeHandle) { return 0; }

