using namespace Valdi::Harmony;
struct Scene {
    ArkUI_NativeNodeAPI_1 api {};
    std::vector<std::unique_ptr<platform::Node>> nativeNodes;
    std::shared_ptr<detail::Backend> backend = std::make_shared<detail::Backend>();
    ArkUIViewManager manager;
    Ref<View> root;
    std::shared_ptr<detail::Node> target, child;
    std::shared_ptr<detail::SnapshotJob> snapshot;
    int completions = 0;
    ArkUI_NodeContentHandle content = reinterpret_cast<ArkUI_NodeContentHandle>(this);

    std::shared_ptr<detail::Node> makeNode() {
        auto native = std::make_unique<platform::Node>();
        auto node = std::make_shared<detail::Node>();
        node->backend = backend;
        node->handle = reinterpret_cast<ArkUI_NodeHandle>(native.get());
        nativeNodes.push_back(std::move(native));
        backend->nodes.push_back(node.get());
        return node;
    }
    Scene() {
        platform::insertions = platform::invalid = 0;
        api.insertChildAt = [](ArkUI_NodeHandle parent, ArkUI_NodeHandle node, int32_t) -> int32_t {
            if (!platform::live(parent)) { ++platform::insertions; return ARKUI_ERROR_CODE_PARAM_INVALID; }
            return platform::insert(node);
        };
        api.removeChild = [](ArkUI_NodeHandle parent, ArkUI_NodeHandle node) -> int32_t {
            assert(platform::live(parent) && platform::live(node));
            return 0;
        };
        api.getTotalChildCount = [](ArkUI_NodeHandle node) -> uint32_t {
            return platform::live(node) ? reinterpret_cast<platform::Node*>(node)->children : 0;
        };
        api.disposeNode = [](ArkUI_NodeHandle node) {
            assert(platform::live(node));
            reinterpret_cast<platform::Node*>(node)->alive = false;
        };
        backend->api = &api;
        manager._backend = backend;
        root = std::make_shared<View>();
        root->node = makeNode();
        root->node->content = content; // Already mounted when the next mount begins.
        target = makeNode();
        child = makeNode();
        child->parent = root->node;
        root->node->children.push_back(child);
    }
    void pending(std::function<void()> callback) {
        snapshot = std::make_shared<detail::SnapshotJob>([this, callback](std::string) {
            ++completions;
            callback();
        });
        child->snapshots.push_back(snapshot); // Exercise subtree, not just the root.
        backend->snapshots.push_back(snapshot);
    }
    void mount(int variant, int index = 0) {
        if (variant == 0) manager.mountRoot(root, content);
        else if (variant == 1) manager.mountRoot(root, content, index);
        else manager.mountRootInParent(root, target->handle, index);
    }
    ~Scene() { manager.shutdown(); }
};

static void requireNoNativeMount(const char* scenario) {
    if (platform::insertions || platform::invalid) {
        std::cerr << "REGRESSION: reentrant mount reached native API: " << scenario << '\n';
        std::exit(75);
    }
}

#ifndef VALDI_REFRESH_TEST
int main(int argc, char** argv) {
    if (argc != 2 && argc != 3) return 2;
    const std::string scenario = argv[1];
    if (scenario == "shutdown") {
        if (argc != 3) return 2;
        const int variant = std::stoi(argv[2]);
        if (variant < 0 || variant > 2) return 2;
        {
            Scene scene;
            scene.pending([&] { scene.manager.shutdown(); });
            bool rejected = false;
            try { scene.mount(variant); } catch (const std::runtime_error&) { rejected = true; }
            assert(rejected && scene.completions == 1 && scene.backend->stopped && !scene.root->node->handle);
            requireNoNativeMount("snapshot completion -> shutdown");
        }
    } else if (scenario == "target-dispose") {
        Scene scene;
        scene.pending([&] { scene.target->dispose(); });
        bool rejected = false;
        try { scene.mount(2); } catch (const std::runtime_error&) { rejected = true; }
        assert(rejected && scene.completions == 1 && scene.root->node->handle && !scene.target->handle);
        requireNoNativeMount("snapshot completion -> target disposal");
    } else if (scenario == "target-index") {
        Scene scene;
        reinterpret_cast<platform::Node*>(scene.target->handle)->children = 1;
        scene.pending([&] { reinterpret_cast<platform::Node*>(scene.target->handle)->children = 0; });
        bool rejected = false;
        try { scene.mount(2, 1); } catch (const std::runtime_error&) { rejected = true; }
        if (!rejected || platform::insertions) {
            std::cerr << "REGRESSION: stale parent index reached native API\n";
            return 75;
        }
    } else if (scenario == "normal") {
        for (int variant = 0; variant < 3; ++variant) {
            Scene scene;
            scene.mount(variant);
            assert(platform::insertions == 1 && platform::invalid == 0 && scene.root->node->handle);
            assert(variant == 2 ? scene.root->node->hostParent == scene.target->handle :
                                 scene.root->node->content == scene.content);
        }
    } else return 2;
    std::cout << "production mount path passed: " << scenario;
    if (argc == 3) std::cout << " variant " << argv[2];
    std::cout << '\n';
}
#endif
